import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { createEmptyBook } from "./paperBook.js";
import {
  BASE_SIZE_USD,
  EXPLORER_BIG_MIN_LIQ_USD,
  PROVEN_BIG_MIN_LIQ_USD,
  READMIT_SIZE_CAP_USD,
  YOUNG_THIN_SIZE_CAP_USD,
} from "./config.js";
import type { CopyBookState, CopyCycleArtifact } from "./types.js";

export function copytradeDataDir(root = process.cwd()): string {
  return (
    process.env.COPYTRADE_DATA_DIR?.trim() ||
    path.join(root, "data", "copytrade")
  );
}

export function bookPath(root = process.cwd()): string {
  return path.join(copytradeDataDir(root), "book.json");
}

export async function loadBook(root = process.cwd()): Promise<CopyBookState> {
  const p = bookPath(root);
  try {
    const raw = await readFile(p, "utf8");
    return JSON.parse(raw) as CopyBookState;
  } catch {
    return createEmptyBook();
  }
}

export async function saveBook(
  book: CopyBookState,
  root = process.cwd(),
): Promise<string> {
  const dir = copytradeDataDir(root);
  await mkdir(dir, { recursive: true });
  const p = bookPath(root);
  await writeFile(p, JSON.stringify(book, null, 2), "utf8");
  return p;
}

export async function writeArtifact(
  artifact: CopyCycleArtifact,
  root = process.cwd(),
): Promise<{ latest: string; stamped: string }> {
  const artifactsDir = path.join(root, "artifacts");
  await mkdir(artifactsDir, { recursive: true });
  const latest = path.join(artifactsDir, "copy_cycle_latest.json");
  const stamp = artifact.ranAt.replace(/[:.]/g, "-");
  const stamped = path.join(artifactsDir, `copy_cycle_${stamp}.json`);
  const body = JSON.stringify(artifact, null, 2);
  await writeFile(latest, body, "utf8");
  await writeFile(stamped, body, "utf8");

  const dataDir = copytradeDataDir(root);
  await mkdir(dataDir, { recursive: true });
  await writeFile(
    path.join(dataDir, "last_cycle.json"),
    body,
    "utf8",
  );
  return { latest, stamped };
}

export async function writeStatusMd(
  artifact: CopyCycleArtifact,
  root = process.cwd(),
): Promise<string> {
  const p = path.join(root, "COPYTRADE_STATUS.md");
  const lines = [
    "# Copy-trade status (paper only)",
    "",
    `- Ran at: **${artifact.ranAt}** (UTC)`,
    `- Mode: paper copy-trade — **$0 real money**`,
    `- Equity: **$${artifact.equityUsd.toFixed(2)}** (cash $${artifact.cashUsd.toFixed(2)}, unrealized $${artifact.unrealizedPnlUsd.toFixed(2)}, realized $${artifact.realizedPnlUsd.toFixed(2)})`,
    `- New copies this run: **${artifact.newCopiesOpened}** (buys detected: ${artifact.newBuysDetected})`,
    `- Open positions: **${artifact.openPositions}** · closed this cycle: **${artifact.closedThisCycle}**`,
    `- Discovery sources: **pumpfun_leaderboard_1w_midtier** + **kolscan.io 7d mid-ranks** (mid-tier / smaller-following printers, not mega whales; each RPC-verified)`,
    `- Continuity: mid-tier opens marked live; opens from inactive/archived source wallets are scrubbed so they do not block MAX_OPEN slots; only NEW copies from mid-tier active list`,
    `- Active wallets: **${artifact.walletsTracked.length}** mid-tier (mega top-6 in whales_archived)`,
    `- Analysis: \`npm run copy-learn\` (win rate / PnL by wallet, exit reason, token age, liquidity, slippage)`,
    "",
    ...learningSection(artifact),
    "## Open positions",
    "",
    ...(artifact.positions.filter((p) => p.status === "open").length
      ? artifact.positions
          .filter((p) => p.status === "open")
          .map(
            (p) =>
              `- ${p.sourceWalletLabel}:${p.symbol ?? p.mint.slice(0, 8)} $${p.sizeUsd.toFixed(2)} @ ${p.entryPriceUsd.toPrecision(4)} (${p.entryPriceSource}) → ${(p.unrealizedPnlPct * 100).toFixed(1)}%${p.partialTakenAt ? ` · partial TP banked +$${(p.partialRealizedPnlUsd ?? 0).toFixed(2)}, trailing` : ""}${p.learning ? ` · tier ${p.learning.walletTier}` : " · legacy"}`,
          )
      : ["- None"]),
    "",
    "## Skip reasons (this cycle)",
    "",
    ...skipCounts(artifact),
    "",
    "## Wallets tracked",
    "",
    ...artifact.walletsTracked.map(
      (w) =>
        `- **${w.label}** \`${w.address}\`${w.provisional ? " _(provisional)_" : ""} — ${w.justification}`,
    ),
    "",
    "## Summary",
    "",
    artifact.summary,
    "",
    "## Blockers",
    "",
    ...(artifact.blockers.length
      ? artifact.blockers.map((b) => `- ${b}`)
      : ["- None"]),
    "",
    "## Skips",
    "",
    ...(artifact.skipped.length
      ? artifact.skipped
          .slice(0, 20)
          .map((s) => `- \`${s.signature.slice(0, 16)}…\` — ${s.reason}`)
      : ["- None"]),
    "",
    "_Old Survival paper trial routine remains PAUSED. Do not resume from this module._",
    "",
  ];
  await writeFile(p, lines.join("\n"), "utf8");
  return p;
}

function learningSection(a: CopyCycleArtifact): string[] {
  if (!a.learningMode || !a.policy) {
    return ["## Learning mode", "", "- OFF (legacy gate stack)", ""];
  }
  const p = a.policy;
  const t = a.learningTuning;
  return [
    "## Learning mode (ON)",
    "",
    `- Enabled 2026-09-24 ~15:36 MDT (config.ts LEARNING_*; set COPYTRADE_LEARNING_MODE=false for the legacy gate stack). Existing book kept (no equity reset); pre-learning positions are untagged "legacy".`,
    `- Roster: ${a.walletsTracked.map((w) => w.label).join(", ")}. Cooker / passthedutcher / onlyljc / Hash / cap / Rilsio / LUKEY / zeropnl (archived 2026-09-28 16:06–20:55 MDT by the old 4-close auto-demote) RESTORED 2026-09-28 ~21:10 MDT at a size cap (raised $10 → $25 on 2026-09-29) — all pass the new suspension rule. Suspended wallets stay on this list (polled, shadow-tracked); do NOT archive on suspension. Tokenized equities skipped.`,
    `- Sizes: explorer **$${p.explorerSizeUsd}**, proven (net+ with ≥${p.provenMinCloses} closes) **≤$${p.provenSizeUsd}**; re-admitted wallets hard-capped $${READMIT_SIZE_CAP_USD}; young/thin-pool cap stays $${YOUNG_THIN_SIZE_CAP_USD}; liquidity tiers: $${p.explorerSizeUsd} needs liq ≥ $${EXPLORER_BIG_MIN_LIQ_USD.toLocaleString("en-US")}, proven $${p.provenSizeUsd} needs liq ≥ $${PROVEN_BIG_MIN_LIQ_USD.toLocaleString("en-US")} (else step down toward $${BASE_SIZE_USD}; unknown liquidity → $${BASE_SIZE_USD})`,
    `- Concurrency: max open **${p.maxOpenPositions}**, per wallet **${p.maxOpenPerWallet}**, unproven total **${p.maxOpenUnprovenTotal}**, total open exposure ≤ **${(p.maxExposurePctOfEquity * 100).toFixed(0)}%** of equity (skip \`max_open_exposure\`; never above cash)`,
    `- OFF in learning: explorer_needs_this_book_win, explorer displacement (scrub_prefer_better_unproven)`,
    `- Kept: mark sanity (upside ≤3×), rug_gap immediate exit, entry_live_below_tx at **${(p.underwaterRefusePct * 100).toFixed(0)}%**, mint cooldown **${p.mintCooldownMs / 3_600_000}h**, one open bag per mint, deep-bleed ban ≤$${p.deepBleedUsd} on qualifying closes (pure-loss ban retired in learning — suspension rule)`,
    `- Exits: base TP +12% / SL −15% → partial **${(p.partialTpFraction * 100).toFixed(0)}%** banked, remainder trails **${(p.trailPct * 100).toFixed(0)}%** from peak (breakeven floor); fixed rug_gap at ≤ −30% exits immediately (even inside open-grace); 6h time-stop`,
    t
      ? `- Auto-tune (n=${t.learningClosed}): TP +${(t.winPct * 100).toFixed(0)}% / SL −${(t.lossPct * 100).toFixed(0)}%${t.tpSlFrozen ? ` **pinned** (non-rug qualifying ${t.nonRugQualifyingCloses ?? 0}/50)` : ""}; promoted ${t.promoted.length}, suspended ${(t.suspended ?? []).length} — ${t.notes.join("; ")}`
      : `- Auto-tune: waiting for ≥20 learning-tagged closes (TP/SL at base +12/−15)`,
    "",
    ...RULES_2026_09_28,
  ];
}

