function skipCounts(a: CopyCycleArtifact): string[] {
  if (!a.skipped.length) return ["- None"];
  const m = new Map<string, number>();
  for (const s of a.skipped) m.set(s.reason, (m.get(s.reason) ?? 0) + 1);
  return [...m.entries()]
    .sort((x, y) => y[1] - x[1])
    .map(([r, n]) => `- ${r}: ${n}`);
}
